import type { Metadata } from "next";
import { Container } from "@/components/container";
import { ItemCard } from "@/components/item-card";
import { PageHeader, PageShell } from "@/components/page-shell";
import { projects } from "@/data/projects";

export const metadata: Metadata = {
  title: "Projects",
};

export default function ProjectsPage() {
  return (
    <PageShell>
      <PageHeader
        label="Projects"
        title="Technical work with clear systems, interfaces, and outcomes."
        description="Add projects in data/projects.ts with summaries, links, repositories, image paths, and the stack used."
      />
      <Container>
        <div className="grid gap-4 py-12 md:grid-cols-2">
          {projects.map((project) => (
            <ItemCard
              key={project.title}
              title={project.title}
              eyebrow={project.year}
              summary={project.summary}
              tags={project.stack}
            >
              <div className="flex flex-wrap gap-3 text-sm">
                {project.href ? (
                  <a className="text-accent hover:underline" href={project.href}>
                    Live
                  </a>
                ) : null}
                {project.repository ? (
                  <a className="text-accent hover:underline" href={project.repository}>
                    Source
                  </a>
                ) : null}
              </div>
            </ItemCard>
          ))}
        </div>
      </Container>
    </PageShell>
  );
}
